import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"微服务架构","description":"","frontmatter":{},"headers":[],"relativePath":"microservice/index.md","filePath":"microservice/index.md","lastUpdated":1781086744000}'),o={name:"microservice/index.md"};function h(l,a,n,d,s,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="微服务架构" tabindex="-1">微服务架构 <a class="header-anchor" href="#微服务架构" aria-label="Permalink to &quot;微服务架构&quot;">​</a></h1><p>微服务是一种分布式系统解决方案，推动细粒度服务的使用，这些服务协同工作，且每个服务都有自己的生命周期。</p><h2 id="什么是微服务" tabindex="-1">什么是微服务 <a class="header-anchor" href="#什么是微服务" aria-label="Permalink to &quot;什么是微服务&quot;">​</a></h2><p>微服务就是一些协同工作的小而自治的服务。它强调的是 很小，专注于做好一件事。</p><p>内聚性是指将相关代码放在一起，在考虑使用微服务的时候，内聚性这一概念很重要。</p><p>Robert C. Martin 有一个对 单一职责原则 的论述：“把因相同原因而变化的东西聚合在一起，而把不同原因而变化的东西分离开来。”该论述很好地强调了内聚性这一概念。</p><p>微服务将这个理念应用到独立的服务上。根据业务边界来确定服务边界，这样就很容易确定某个功能代码应该放在哪里。而且由于该服务专注于某个边界以内，因此可以很好地避免由于代码库过大衍生出的很多相关问题。</p><h2 id="使用微服务的好处" tabindex="-1">使用微服务的好处 <a class="header-anchor" href="#使用微服务的好处" aria-label="Permalink to &quot;使用微服务的好处&quot;">​</a></h2><p>微服务有很多不同好处，其中很多好处也适用于任何一个分布式系统。但相对于分布式系统或者面向服务架构而言，微服务要略胜一筹，他会把这些好处推到极致。</p><h3 id="_1-技术异构性" tabindex="-1">1. 技术异构性 <a class="header-anchor" href="#_1-技术异构性" aria-label="Permalink to &quot;1. 技术异构性&quot;">​</a></h3><p>可以在不同的服务中使用最适合该服务的技术。</p><h3 id="_2-弹性" tabindex="-1">2. 弹性 <a class="header-anchor" href="#_2-弹性" aria-label="Permalink to &quot;2. 弹性&quot;">​</a></h3><p>弹性工程系的关键概念是 舱壁。如果系统中的一个组件不可用了，但并没有导致级联故障，那么系统的其他组件还可以正常运行。服务边界就是一个很显然的舱壁。对于单体应用，如果服务不可用，那么所有功能都不可用。虽然我们可以通过将同样的实例运行在不同的机器上来降低功能完全不可用的概率，微服务系统本很就能很好地处理服务不可用和功能降级的问题。</p><h3 id="_3-扩展" tabindex="-1">3. 扩展 <a class="header-anchor" href="#_3-扩展" aria-label="Permalink to &quot;3. 扩展&quot;">​</a></h3><p>单体应用只能作为一个整体进行扩展。即使系统中只用一小部分存在性能问题，也需要对整个服务进行扩展。而对于微服务架构，我们可以只对需要扩展的服务进行扩展。</p><h3 id="_4-简化部署" tabindex="-1">4. 简化部署 <a class="header-anchor" href="#_4-简化部署" aria-label="Permalink to &quot;4. 简化部署&quot;">​</a></h3><p>在几百万行的单体应用中，即使修改了一行代码，也要对整个应用进行重新部署才能发布该变更。这种部署的影响很大，风险很高，因此相关人员不敢轻易做部署。在微服务架构中，各个服务的部署是独立的，这样可以更快地对特定部分的代码进行部署。如果真的出了问题，也只会影响一个服务，并且容易快速回滚。</p><h3 id="_5-与组织结构相匹配" tabindex="-1">5. 与组织结构相匹配 <a class="header-anchor" href="#_5-与组织结构相匹配" aria-label="Permalink to &quot;5. 与组织结构相匹配&quot;">​</a></h3><p>微服务架构可以很好地将架构与组织结构相匹配，避免出现过大的代码库，从而获得理想的团队大小和生产力。</p><h3 id="_6-可组合型" tabindex="-1">6. 可组合型 <a class="header-anchor" href="#_6-可组合型" aria-label="Permalink to &quot;6. 可组合型&quot;">​</a></h3><p>分布式系统和面向服务架构声称的主要好处是易于重用已有功能。而在微服务架构中，根据不同的目的，人们可以通过不同的方式使用同一个功能。在现代社会中，我们需要考虑的应用程序种类繁多，包括Web，原生应用，移动端Web，平板应用，可穿戴设备等，针对每一种应用场景我们都可以考虑如何对已有功能进行组合来实现这些应用。</p><p>在微服务架构中，系统会开放很多接口供外部使用，所以我们可以使用不同的方式。组合不同的API构建应用；而相对而言，单体应用程序只能提供一个非常粗粒度的接口供外部使用。</p><h3 id="_7-对可替代性的优化" tabindex="-1">7. 对可替代性的优化 <a class="header-anchor" href="#_7-对可替代性的优化" aria-label="Permalink to &quot;7. 对可替代性的优化&quot;">​</a></h3><p>对于大众性组织而言，很可能存在庞大而丑陋的遗留系统。这些系统无人敢碰，却对公司的运营至关重要。这些系统之所以没有被取代的原因很简单：工作量很大，并且风险很高。</p><p>当使用微服务架构时，重新实现某一个服务或者是删除该服务都是相对可操作的。使用微服务架构的团队可以在需要时轻易重写服务，或者删除不再使用的服务。。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>《微服务设计》 Sam Newman著，崔力强 张骏 译，2016</p><p><a href="https://martinfowler.com/articles/microservices.html" target="_blank" rel="noreferrer">Microservices</a></p>',28)])])}const m=e(o,[["render",h]]);export{_ as __pageData,m as default};
